import { connection } from "next/server";
import { listBooks, type Book } from "@/lib/books";
import { markFinishedAction } from "./actions";
import { AddBookForm } from "./add-book-form";
import { MarkFinishedButton } from "./mark-finished-button";
import { formatDate } from "./format";

function BookRow({ book }: { book: Book }) {
  return (
    <li className="book-row">
      <div>
        <Link href={`/books/${book.id}`} className="book-title">
          {book.title}
        </Link>
        <div className="muted">
          {book.author} ·{" "}
          {book.finishedAt ? `finished ${formatDate(book.finishedAt)}` : `added ${formatDate(book.addedAt)}`}
        </div>
      </div>
      {book.status === "reading" && <MarkFinishedButton action={markFinishedAction.bind(null, book.id)} />}
    </li>
  );
}

export default async function Home() {
  await connection(); // always read the latest books.json, never a build-time snapshot
  const books = await listBooks();

  const reading = books
    .filter((b) => b.status === "reading")
    .sort((a, b) => b.addedAt.localeCompare(a.addedAt));
  const finished = books
    .filter((b) => b.status === "finished")
    .sort((a, b) => (b.finishedAt ?? "").localeCompare(a.finishedAt ?? ""));

  return (
    <>
      <section>
        <h2>Currently reading</h2>
        {reading.length ? (
          <ul className="book-list">
            {reading.map((b) => (
              <BookRow key={b.id} book={b} />
            ))}
          </ul>
        ) : (
          <p className="muted">Nothing on the go. Add a book below.</p>
        )}
      </section>

      <section>
        <h2>Finished</h2>
        {finished.length ? (
          <ul className="book-list">
            {finished.map((b) => (
              <BookRow key={b.id} book={b} />
            ))}
          </ul>
        ) : (
          <p className="muted">No finished books yet.</p>
        )}
      </section>

      <AddBookForm />
    </>
  );
}
"}

