    await expect(addBook({ title: " ", author: "A" })).rejects.toThrow(ValidationError);
    await expect(addBook({ title: "T", author: "" })).rejects.toThrow(ValidationError);
    await expect(addBook({ title: "x".repeat(201), author: "A" })).rejects.toThrow(ValidationError);
