import { revalidatePath } from "next/cache";
import { addBook, markFinished, ValidationError } from "@/lib/books";

export type AddBookState = {
  error: string | null;
  // Echo the submitted values back so a rejected form keeps what was typed.
  values: { title: string; author: string; notes: string };
};

function field(formData: FormData, name: string): string {
  const value = formData.get(name);
  return typeof value === "string" ? value : "";
}

export async function addBookAction(_prev: AddBookState, formData: FormData): Promise<AddBookState> {
  const values = {
    title: field(formData, "title"),
    author: field(formData, "author"),
    notes: field(formData, "notes"),
  };

  try {
    await addBook(values);
  } catch (err) {
    if (err instanceof ValidationError) return { error: err.message, values };
    throw err;
  }

  revalidatePath("/");
  return { error: null, values: { title: "", author: "", notes: "" } };
}

export async function markFinishedAction(id: string): Promise<void> {
  const book = await markFinished(id);
  if (!book) return;
  revalidatePath("/");
  revalidatePath(`/books/${id}`);
}

